    <div class="invoice-status"><span class="status-dot"/>{{status(effectiveStatus(latest))}}</div><button class="secondary full" @click="refresh"><RefreshCw :size="17"/>{{tr('Я оплатил — проверить транзакцию','I’ve paid — check transaction')}}</button><p class="poll-label">{{tr('Статус обновляется каждые 2 секунды. Кнопка не подтверждает оплату без проверки сети.','Status refreshes every 2 seconds. The button cannot confirm payment without network verification.')}}</p></template>
